// process.env.TZ changes the time zone at once, as in Node.js: Date's local time and Intl.
module.exports = function run() {
  const at = new Date(Date.UTC(2024, 0, 15, 12, 0, 0));
  process.env.TZ = "UTC";
  console.log("UTC", at.getHours(), at.getTimezoneOffset(), Object.keys(process.env).includes("TZ"));
  process.env.TZ = "Asia/Tokyo";
  console.log("Tokyo", at.getHours(), at.getTimezoneOffset(), process.env.TZ);
  process.env.TZ = "America/New_York";
  console.log("New York", at.getHours(), at.getTimezoneOffset(), new Intl.DateTimeFormat("en-US", { hour: "numeric", hour12: false }).format(at));
};
